{
  "findings": [
    {
      "finding": "Statement the paper does not support",
      "level": 1,
      "severity": "blocking",
      "suggestion": "Replace the specific quantitative claim *“with no vaccination, more than 5 more people are infectious at year 20 than in this world”* with a qualitative description that matches the paper’s results, e.g.: *“with no vaccination the number of infectious individuals is higher at year 20, reflecting the negative sensitivity of the reproduction number to the vaccination rate*”."
    },
    {
      "finding": "Statement labelled the paper’s but is really a teaching choice (mis‑attribution)",
      "level": 2,
      "severity": "blocking",
      "suggestion": "Remove the quotation *“The paper shows that vaccinating every newborn would eliminate tuberculosis within ten years.”* and re‑phrase it as a teacher‑generated scenario, e.g.: *“Imagine a situation where every newborn is vaccinated; the model predicts that, if the effective reproduction number falls below 1, the disease would eventually die out (the paper does not give a ten‑year timeline).”*"
    },
    {
      "finding": "Claim worded more strongly than its measurement",
      "level": 3,
      "severity": "advice",
      "suggestion": "Tone down the claim *“the epidemic doubles in size and the disease can never be controlled”* to reflect what the analysis actually shows, e.g.: *“doubling the progression rate leads to a larger exposed population and makes control more difficult, as the basic reproduction number increases.”*"
    },
    {
      "finding": "What‑if that cannot teach what its level is about",
      "level": 3,
      "severity": "advice",
      "suggestion": "Change the what‑if description to focus on the exposed compartment, e.g.: *“What if the progression rate (γ) were twice as fast? Observe how the exposed class rises more quickly and how this influences the subsequent infectious class.”*"
    },
    {
      "finding": "Confusing word",
      "level": 2,
      "severity": "advice",
      "suggestion": "Replace the phrase *“vaccinating every newborn”* with *“vaccinating a proportion π of susceptible individuals (including newborns)”* to align the wording with the model’s vaccination parameter π."
    }
  ]
}
